%[text] # EEG processing for NF systems
%[text] 
%[text] Jorge Ethan Mc Kelligan Desilos - A01412313
%[text] Marián Pérez Cerecedo - A01412386
%[text] Andrés Eduardo García Sáenz - A015633674
%[text] Sergio Romero Martínez - A01781725
%[text] 
%[text] **Instrucciones:** 
%[text] 1\. Use one EEG recording that you and your team recorded in the lab, and that is related to your challenge. The recording must be of at least 3 minutes, and it must include two different conditions (e.g. rest, attention, meditation, etc...). Alternatively, you can use an EEG signal from a database, but with the same duration, and conditions criteria. The experimental conditions must be related to your challenge.
%[text] 2\. Load your signal into EEGLAB, and show the sample rate, number of channels, and duration of your recording. 
%[text] 3\. Use a band-pass filter to remove drift, and powerline noise. Specify the frequency ranges used and explain your choice. 
%[text] 4\. Estimate the neuromarker (across time) you are interested in monitoring for your NF system, for all the duration of your EEG recording. Explain why and how you estimated such neuromarker. Also, if your neuromarker is the result of the combination of multiple channels, explain this process as well. 
%[text] 5\. Generate a report to document the previous steps, including a conclusion related to this analysis in the context of your challenge. Also make sure to include the following figures: 
%[text] (1) Raw EEG signals (across time), identifying the times of each condition. 
%[text] (2) EEG signals (across time) after the band-pass filter, identifying the times of each condition. 
%[text] (3) Neuromarker (across time), identifying the times of each condition. 
%[text] 
%[text] **Base de datos**:  [https://ieee-dataport.org/open-access/dasps-database ](https://ieee-dataport.org/open-access/dasps-database)
%[text] Las condiciones que presenta son los siguientes
%[text] ![](text:image:7f60)
fs = 128;
%Datos del paciente uno
path = 'Raw data mat/S01.mat';
paciente_1_mat = load(path); %struct. Tambien lo tenemos con las grabaciones seguidas 
labels = paciente_1.labels %[output:8a8efa1a]
valence = labels(:, 1);
arousal = labels(:, 2);

% grabaciones impar significa cuando recitaba el psicologo la situacion de
% estres, grabaciones par cuando la persona recitaba lo que se le conto
datos_p1 = paciente_1.data;
size(datos_p1) %[output:036fbe67]
%[text] El tamaño es de 14 eelctrodos x 1920 x 12 
%[text] - 14 derivaciones
%[text] - 1920 muestras = 15 seg
%[text] - Las 6 situaciones con fases  \
%[text] 1. Escucha: par
%[text] 2. Recall: impar \
%[text] Para usar eeglab correctamente contrajimos las 12 situaciones en una lectura seguida 
%[text] Pasamos de 12 grabaciones de 1920 muestras =\> 15 segundos
%[text] Una sola grabacion de 23040 muestras =\> 3 minutos
%[text] 
EEG = pop_loadset('C:\Users\jorge\Documents\Tec\Uni\6. Sexto Semestre\EEG_Luzma\EEG processing for NF systems\S01_eeglab.set')  %[output:08c63ac0] %[output:10ad4049]
%Misma funcion que usa la GUI de eeglab, pero para script
%[text] Se pueden ver claramente los 14 canales
chan_num = EEG.nbchan %[output:0b587f36]
%[text] Canales nombres
chan_names = EEG.chanlocs %[output:234a793a]
%[text] El f3 es el 3 y el f4 es el 12
%[text] 
%[text] Sampling rate
fs = EEG.srate %[output:04f0a7b5]
%[text] La duracion es de 3 minutos. 6 historias con dos estados. Escuchando el relato del psicologo, recitandolo en su mente.
samples = EEG.pnts %[output:770cbd50]
seconds = samples / fs %[output:78440ff3]
minutes = seconds / 60 %[output:2d8c28cc]
%%
%Filtrado de señal
% Filtro pasa-bandas 1-45 Hz, elimina el drift y la señal de europa como de
% america. las ondas de interes (alpha) siguen estando presentes para el
% analisis. 
EEG_filt = pop_eegfiltnew(EEG, 1, 45); %Es la misma funcion que usa la GUI de eeglab %[output:11f15485]
EEG_filt = eeg_checkset(EEG_filt);
%%
%[text] Fourier de la señal filtrada y no filtrada
N  = EEG.pnts;
fs = EEG.srate;
f  = (0:N/2) * (fs/N);   % eje de frecuencia en Hz (solo positivo)

fourier_og  = abs(fft(EEG.data(1,:)));
fourier_new = abs(fft(EEG_filt.data(1,:)));

% Solo mitad positiva del espectro
mag_og  = fourier_og(1:N/2+1);
mag_new = fourier_new(1:N/2+1);

figure; %[output:030c7279]
subplot(2,1,1); %[output:030c7279]
plot(f, mag_og); %[output:030c7279]
xlabel('Frecuencia (Hz)'); ylabel('Amplitud'); %[output:030c7279]
title('FFT - Sin filtro (AF3)'); %[output:030c7279]
xlim([0 64]); grid on; %[output:030c7279]

subplot(2,1,2); %[output:030c7279]
plot(f, mag_new); %[output:030c7279]
xlabel('Frecuencia (Hz)'); ylabel('Amplitud'); %[output:030c7279]
title('FFT - Con filtro 1-45 Hz (AF3)'); %[output:030c7279]
xlim([0 64]); grid on; %[output:030c7279]
%[text] Podemos ver que si habia ruido de DC en 0 hz, pero no de linea (50-60 hz). Igualmente mejora la calidad. Probablemente por filtro interno del eeg que rechaza bandas que no nos son utiles en EEG.
%%
% Colores
color_listen = [0.2  0.6  0.9];
color_recall = [0.6  0.8  0.3];
t_axis = (0:EEG.pnts-1) / EEG.srate;
ch_names = {EEG.chanlocs.labels};
offset = 150;
%[text] 
t_axis = (0:EEG.pnts-1) / EEG.srate;
cl = [0.2 0.6 0.9];  cr = [0.6 0.8 0.3];   % Listen / Recall
raw  = EEG.data([3 12], :);
filt = EEG_filt.data([3 12], :);
ch_names = {'F3','F4'};

% --- Shading helper (reutilizado en las 3 figuras) ---
function shade(cl, cr, ylo, yhi)
    for i = 1:12
        fill([(i-1)*15 i*15 i*15 (i-1)*15],[ylo ylo yhi yhi], ...
             cl*(mod(i,2)==1)+cr*(mod(i,2)==0), ...
             'EdgeColor','none','FaceAlpha',0.4,'HandleVisibility','off');
    end
end

% --- Fig 1: Crudo ---
figure('Name','Raw F3 & F4'); %[output:716919e2]
for k = 1:2 %[output:group:1b5840f9]
    subplot(2,1,k); hold on; %[output:716919e2]
    shade(cl, cr, min(raw(k,:)), max(raw(k,:)));
    plot(t_axis, raw(k,:), 'k', 'LineWidth', 0.6);
    title(['Raw ' ch_names{k}]); xlabel('Tiempo (s)'); ylabel('\muV');
    xlim([0 180]); grid on; hold off;
end %[output:group:1b5840f9]

% --- Fig 2: Filtrado ---
figure('Name','Filtered F3 & F4'); %[output:576d5cba]
for k = 1:2 %[output:group:4a90c397]
    subplot(2,1,k); hold on; %[output:576d5cba]
    shade(cl, cr, min(filt(k,:)), max(filt(k,:)));
    plot(t_axis, filt(k,:), 'k', 'LineWidth', 0.6);
    title(['Filtrado ' ch_names{k}]); xlabel('Tiempo (s)'); ylabel('\muV');
    xlim([0 180]); grid on; hold off;
end %[output:group:4a90c397]


% --- Fig 3: Overlay crudo vs filtrado ---
figure('Name','Raw vs Filtered'); %[output:733bc5cc]
for k = 1:2 %[output:group:3b189a7f]
    subplot(2,1,k); hold on; %[output:733bc5cc]
    shade(cl, cr, min(raw(k,:)), max(raw(k,:)));
    hr = plot(t_axis, raw(k,:),  'Color', [0.7 0.7 0.7], 'LineWidth', 0.6);
    hf = plot(t_axis, filt(k,:), 'k', 'LineWidth', 1.2);
    hr.Color(4) = 0.4;
    title([ch_names{k} '  Crudo vs Filtrado']);
    xlabel('Tiempo (s)'); ylabel('\muV');
    xlim([0 180]); grid on;
    legend([hr hf],'Crudo','Filtrado','Location','best');
    hold off;
end %[output:group:3b189a7f]

figure('Name','Raw vs Filtered - Zoom'); %[output:51f5e0d6]
zoom_range = t_axis >= 30 & t_axis <= 35;   % 5 segundos

for k = 1:2 %[output:group:12374d5f]
    subplot(2,1,k); hold on; %[output:51f5e0d6]
    hr = plot(t_axis(zoom_range), raw(k,zoom_range),  'Color',[0.9 0.3 0.2], 'LineWidth', 1.0);
    hf = plot(t_axis(zoom_range), filt(k,zoom_range), 'Color',[0.1 0.1 0.1], 'LineWidth', 1.5);
    hr.Color(4) = 0.6;
    title([ch_names{k} ' — Zoom 30-35 s']);
    xlabel('Tiempo (s)'); ylabel('\muV'); grid on;
    legend([hr hf],'Crudo','Filtrado','Location','best');
    hold off;
end %[output:group:12374d5f]
%[text] Como podemos ver en esta grafica el cambio despues del filtrado es muy sutil. pero si hay un cambio, porque como vimos en las graficas de fourier si habia potencia en frecuencia 0 hz
%%
%[text] Frontal Alpha Assymetry
%% FAA Neuromarker — F3/F4
fs = EEG_filt.srate;
win_samp = round(2 * fs);
step_samp = round(0.5 * fs);
alpha_low = 8; alpha_high = 13;

data_F3 = EEG_filt.data(3, :);
data_F4 = EEG_filt.data(12, :);

n_samp = size(EEG_filt.data, 2);
time_faa = []; faa_values = [];

for t = 1:step_samp:(n_samp - win_samp + 1)
    [pxx_F3, f] = pwelch(data_F3(t:t+win_samp-1), win_samp, win_samp/2, [], fs);
    [pxx_F4, ~] = pwelch(data_F4(t:t+win_samp-1), win_samp, win_samp/2, [], fs);
    idx = f >= alpha_low & f <= alpha_high;
    faa_values(end+1) = log(mean(pxx_F4(idx))) - log(mean(pxx_F3(idx)));
    time_faa(end+1) = (t + win_samp/2) / fs;
end

%% Plot
color_listen = [0.6 0.8 1.0];
color_recall = [1.0 0.8 0.6];

figure('Name','FAA Neuromarker'); %[output:477ac6a7]
ymin = min(faa_values) - 0.2; ymax = max(faa_values) + 0.2;
hold on; %[output:477ac6a7]

for i = 1:12
    t0 = (i-1)*15; t1 = i*15;
    c = color_listen * (mod(i,2)==1) + color_recall * (mod(i,2)==0);
    fill([t0 t1 t1 t0], [ymin ymin ymax ymax], c, ... %[output:477ac6a7]
        'EdgeColor','none', 'FaceAlpha',0.50, 'HandleVisibility','off'); %[output:477ac6a7]
end

h1 = fill(nan, nan, color_listen, 'FaceAlpha',0.4, 'EdgeColor','none'); %[output:477ac6a7]
h2 = fill(nan, nan, color_recall, 'FaceAlpha',0.4, 'EdgeColor','none'); %[output:477ac6a7]
h_faa = plot(time_faa, faa_values, 'k', 'LineWidth', 1.5); %[output:477ac6a7]
h_zero = yline(0, '--r', 'LineWidth', 1); %[output:477ac6a7]

xlabel('Tiempo (s)'); %[output:477ac6a7]
ylabel('FAA = ln(\alpha_{F4}) - ln(\alpha_{F3})'); %[output:477ac6a7]
title('Frontal Alpha Asymmetry (FAA) - S01'); %[output:477ac6a7]
legend([h1, h2, h_faa, h_zero], ... %[output:477ac6a7]
    'Listen (psicólogo)', 'Recall (participante)', 'FAA', 'FAA = 0', ... %[output:477ac6a7]
    'Location','best'); %[output:477ac6a7]
xlim([0 180]); ylim([ymin ymax]); grid on; hold off; %[output:477ac6a7]

%% Estadísticas por fase
fprintf('FAA media Listen: %.4f\n', mean(faa_values(time_faa <= 90))); %[output:438196bb]
fprintf('FAA media Recall: %.4f\n', mean(faa_values(time_faa > 90))); %[output:1052e2bb]
%[text] La teoria de la FAA (Frontal alpha asymmetry) segun Davidson nos dice que mayor activacion frontal izquierda se asocia con estados de aproximacion y afecto positivo, en cambio mayor activacion frontal derecha nos indica evitacion y ansiedad.
%[text] 
%[text] Para calcularlo usamos una ventana deslizante de 2 seg con paso de 0.5 con overlap de 75%. Usamos pwelch en caad ventana. Extrajimos las frecuencias alfa de interes 8-13 hz y se le saca la media de la PSD. 
%[text] Finalmente se resta el logaritmo natural de lo que ya habiamos sacado de la media. Derecho- izquierdo.

